CREATE TABLE "AdminCreds" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Login" varchar NOT NULL,
    "PasswordHash" varchar NOT NULL,
    "Salt" varchar NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "Role" integer NOT NULL,
    CONSTRAINT "PK_AdminCreds" PRIMARY KEY ("Id")
);


CREATE TABLE "AppBalance" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Amount" numeric NOT NULL,
    "LowerThreshold" numeric NOT NULL,
    "LowerThresholdUpdatedAt" timestamp with time zone,
    "LowerThresholdAdminIdUpdatedBy" integer,
    "BalanceAmountUpdatedAt" timestamp with time zone,
    "BalanceAmountAdminIdUpdatedBy" integer,
    CONSTRAINT "PK_AppBalance" PRIMARY KEY ("Id")
);


CREATE TABLE "GameParams" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BaseWinChance" real NOT NULL,
    "MinDepositAmount" integer NOT NULL,
    "MinRoundsCountForWithdrawal" integer NOT NULL,
    "MinWinChance" real NOT NULL,
    "MaxWinChance" real NOT NULL,
    "ChanceDecPerThrowMin" real NOT NULL,
    "ChanceDecPerThrowMax" real NOT NULL,
    "ChanceDecPerRotation" real NOT NULL,
    "MinRotationWinChance" real NOT NULL,
    "MinMultiplier" real NOT NULL,
    "MaxMultiplier" real NOT NULL,
    "InitialBalanceLoss" real NOT NULL,
    "DeviationChance" real NOT NULL,
    "MaxDeviationPercent" real NOT NULL,
    "MinGamesForBoost" integer NOT NULL,
    "WinBoostChance" real NOT NULL,
    "WinBoostMultiplier" real NOT NULL,
    "HardResetChance" real NOT NULL,
    "ControlGoal" real NOT NULL,
    "ReelSpeed" real NOT NULL,
    "UprightThresholdForLine" real NOT NULL,
    "ProbabilityFor10" real,
    "ProbabilityFor5" real,
    "ProbabilityFor3" real,
    "ProbabilityFor2" real,
    "ProbabilityFor1_5" real,
    "BaseMultiplierProbability" real,
    CONSTRAINT "PK_GameParams" PRIMARY KEY ("Id")
);


CREATE TABLE "Players" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TelegramId" bigint NOT NULL,
    "Name" varchar NOT NULL,
    "AvatarUrl" varchar NOT NULL,
    "RegisteredInAppAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Players" PRIMARY KEY ("Id")
);


CREATE TABLE "ProcessingWebhookLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RawRequest" text NOT NULL,
    "HttpMethod" character varying(10) NOT NULL,
    "ContentType" character varying(100),
    "IpAddress" character varying(45),
    "UserAgent" character varying(500),
    "IsSignatureValid" boolean NOT NULL,
    "ProcessingStatus" character varying(50) NOT NULL,
    "ErrorMessage" text,
    "TransactionId" character varying(100),
    "WebhookType" character varying(50),
    "Result" character varying(100),
    "OrderId" character varying(100),
    "MerchantId" character varying(100),
    "ReceivedAt" timestamp with time zone NOT NULL,
    "ProcessedAt" timestamp with time zone,
    CONSTRAINT "PK_ProcessingWebhookLogs" PRIMARY KEY ("Id")
);


CREATE TABLE "TransactionStatuses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar NOT NULL,
    CONSTRAINT "PK_TransactionStatuses" PRIMARY KEY ("Id")
);


CREATE TABLE "TransactionTypes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar NOT NULL,
    CONSTRAINT "PK_TransactionTypes" PRIMARY KEY ("Id")
);


CREATE TABLE "Bans" (
    "PlayerId" integer NOT NULL,
    "BanReason" varchar NOT NULL,
    "BannedAt" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Bans" PRIMARY KEY ("PlayerId"),
    CONSTRAINT "FK_Bans_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "BansHistory" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" integer NOT NULL,
    "BanReason" varchar NOT NULL,
    "BannedAt" timestamp with time zone NOT NULL,
    "UnbannedAt" timestamp with time zone,
    CONSTRAINT "PK_BansHistory" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BansHistory_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "GameRounds" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" integer NOT NULL,
    "Bet" numeric NOT NULL,
    "IsWin" boolean NOT NULL,
    "FinishedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_GameRounds" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_GameRounds_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "InvitedPlayers" (
    "PlayerIdInvited" integer NOT NULL,
    "PlayerIdInvitedBy" integer NOT NULL,
    "InvitedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_InvitedPlayers" PRIMARY KEY ("PlayerIdInvited", "PlayerIdInvitedBy"),
    CONSTRAINT "FK_InvitedPlayers_Players_PlayerIdInvited" FOREIGN KEY ("PlayerIdInvited") REFERENCES "Players" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InvitedPlayers_Players_PlayerIdInvitedBy" FOREIGN KEY ("PlayerIdInvitedBy") REFERENCES "Players" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "PlayersBalance" (
    "PlayerId" integer NOT NULL,
    "Amount" numeric NOT NULL,
    CONSTRAINT "PK_PlayersBalance" PRIMARY KEY ("PlayerId"),
    CONSTRAINT "FK_PlayersBalance_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "PlayersOptions" (
    "PlayerId" integer NOT NULL,
    "WinChance" real NOT NULL,
    "Wallet" character varying(100),
    "Currency" varchar,
    "PayoutMethod" varchar NOT NULL,
    "PaymentMethod" varchar NOT NULL,
    "PaymentDetailType" character varying(50) NOT NULL,
    CONSTRAINT "PK_PlayersOptions" PRIMARY KEY ("PlayerId"),
    CONSTRAINT "FK_PlayersOptions_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ReferralLinks" (
    "PlayerId" integer NOT NULL,
    "Link" varchar NOT NULL,
    CONSTRAINT "PK_ReferralLinks" PRIMARY KEY ("PlayerId"),
    CONSTRAINT "FK_ReferralLinks_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE TABLE "MoneyTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" integer NOT NULL,
    "StatusId" integer NOT NULL,
    "TransactionTypeId" integer NOT NULL,
    "Amount" numeric NOT NULL,
    "ProcessingOrderId" character varying(100),
    "PaymentUrl" character varying(500),
    "PaymentGateway" character varying(50),
    "Currency" character varying(10),
    "ExchangeRate" numeric,
    "IsProcessingSuccess" boolean,
    "ProcessingError" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "ProcessedAt" timestamp with time zone,
    CONSTRAINT "PK_MoneyTransactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MoneyTransactions_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_MoneyTransactions_TransactionStatuses_StatusId" FOREIGN KEY ("StatusId") REFERENCES "TransactionStatuses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_MoneyTransactions_TransactionTypes_TransactionTypeId" FOREIGN KEY ("TransactionTypeId") REFERENCES "TransactionTypes" ("Id") ON DELETE CASCADE
);


CREATE TABLE "PlayersPlayedRoundsStatisticsForWithdrawals" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" integer NOT NULL,
    "DepositTransactionId" integer,
    "PlayedRoundsCount" integer NOT NULL,
    CONSTRAINT "PK_PlayersPlayedRoundsStatisticsForWithdrawals" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PlayersPlayedRoundsStatisticsForWithdrawals_MoneyTransactio~" FOREIGN KEY ("DepositTransactionId") REFERENCES "MoneyTransactions" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_PlayersPlayedRoundsStatisticsForWithdrawals_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);


CREATE INDEX "IX_BansHistory_PlayerId" ON "BansHistory" ("PlayerId");


CREATE INDEX "IX_GameRounds_PlayerId" ON "GameRounds" ("PlayerId");


CREATE UNIQUE INDEX "IX_InvitedPlayers_PlayerIdInvited" ON "InvitedPlayers" ("PlayerIdInvited");


CREATE INDEX "IX_InvitedPlayers_PlayerIdInvitedBy" ON "InvitedPlayers" ("PlayerIdInvitedBy");


CREATE INDEX "IX_MoneyTransactions_CreatedAt" ON "MoneyTransactions" ("CreatedAt");


CREATE INDEX "IX_MoneyTransactions_PlayerId" ON "MoneyTransactions" ("PlayerId");


CREATE INDEX "IX_MoneyTransactions_ProcessingOrderId" ON "MoneyTransactions" ("ProcessingOrderId");


CREATE INDEX "IX_MoneyTransactions_StatusId" ON "MoneyTransactions" ("StatusId");


CREATE INDEX "IX_MoneyTransactions_TransactionTypeId" ON "MoneyTransactions" ("TransactionTypeId");


CREATE INDEX "IX_PlayersPlayedRoundsStatisticsForWithdrawals_DepositTransact~" ON "PlayersPlayedRoundsStatisticsForWithdrawals" ("DepositTransactionId");


CREATE INDEX "IX_PlayersPlayedRoundsStatisticsForWithdrawals_PlayerId" ON "PlayersPlayedRoundsStatisticsForWithdrawals" ("PlayerId");


CREATE INDEX "IX_ProcessingWebhookLogs_OrderId" ON "ProcessingWebhookLogs" ("OrderId");


CREATE INDEX "IX_ProcessingWebhookLogs_ReceivedAt" ON "ProcessingWebhookLogs" ("ReceivedAt");


CREATE INDEX "IX_ProcessingWebhookLogs_TransactionId" ON "ProcessingWebhookLogs" ("TransactionId");


